- (UITableViewCell *)tableView:(UITableView *)tableView cellForRowAtIndexPath:(NSIndexPath *)path{
 if(self.actions){UITableViewCell *cell=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleDefault reuseIdentifier:nil];cell.backgroundColor=[UIColor colorWithWhite:0 alpha:.12];BOOL photo=Array(self.work[@"images"]).count>0;cell.textLabel.text=@[photo?@"保存当前图片":@"保存视频",@"保存封面",@"保存音频",@"复制文案",@"复制分享链接"][path.row];cell.imageView.image=[UIImage systemImageNamed:@[photo?@"photo":@"video",@"photo.on.rectangle",@"music.note",@"doc.on.doc",@"square.and.arrow.up"][path.row]];cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return cell;}
