- (void)notifyKey:(NSString *)key{if([key isEqualToString:@"douglass.force120"]){DGRefreshRateApply();return;}if([key hasPrefix:@"douglass.eq."]||[key isEqualToString:@"douglass.dolby"]){DGRefreshAudioPreferences();return;}NSString *notification=[key hasPrefix:@"douglass.filter."]?@"DGFiltersChanged":([key isEqualToString:@"douglass.quality"]||[key isEqualToString:@"douglass.highFPS"])?@"DGPlaybackQualityChanged":@"DouGlassSettingsChanged";[NSNotificationCenter.defaultCenter postNotificationName:notification object:nil];}
- (void)toggleChanged:(UISwitch *)control{NSString *key=control.accessibilityIdentifier;if([key isEqualToString:@"douglass.backgroundAudio"])DGHaptic();[NSUserDefaults.standardUserDefaults setBool:control.on forKey:key];[self notifyKey:key];}
- (NSDictionary *)rowForControl:(UIView *)control{for(NSArray *section in [self rows])for(NSDictionary *row in section)if([row[@"key"]isEqualToString:control.accessibilityIdentifier])return row;return @{};}
- (void)syncEQControls{for(UITableViewCell *cell in _table.visibleCells){if([cell.accessoryView isKindOfClass:UISwitch.class]&&[cell.accessoryView.accessibilityIdentifier isEqualToString:@"douglass.eq.enabled"])((UISwitch *)cell.accessoryView).on=[NSUserDefaults.standardUserDefaults boolForKey:@"douglass.eq.enabled"];for(UIView *stack in cell.contentView.subviews)for(UIView *view in stack.subviews)if([view isKindOfClass:UISegmentedControl.class]&&[view.accessibilityIdentifier isEqualToString:@"douglass.eq.preset"])((UISegmentedControl *)view).selectedSegmentIndex=[NSUserDefaults.standardUserDefaults integerForKey:@"douglass.eq.preset"];}}
- (void)rangeChanged:(UISlider *)control{NSDictionary *row=[self rowForControl:control];double step=[row[@"step"]doubleValue],value=round(control.value/step)*step;[NSUserDefaults.standardUserDefaults setDouble:value forKey:control.accessibilityIdentifier];for(UIView *view=control.superview;view;view=view.superview)if([view isKindOfClass:DGSettingControlCell.class]){((DGSettingControlCell *)view).heading.text=[self rangeTitle:row value:value];break;}if([control.accessibilityIdentifier hasPrefix:@"douglass.eq."]){[NSUserDefaults.standardUserDefaults setBool:YES forKey:@"douglass.eq.enabled"];[NSUserDefaults.standardUserDefaults setInteger:4 forKey:@"douglass.eq.preset"];}[self syncEQControls];[self notifyKey:control.accessibilityIdentifier];}
- (void)segmentsChanged:(UISegmentedControl *)control{NSString *key=control.accessibilityIdentifier;NSInteger selected=control.selectedSegmentIndex;[NSUserDefaults.standardUserDefaults setInteger:selected forKey:key];if([key isEqualToString:@"douglass.danmaku.color"])[NSUserDefaults.standardUserDefaults removeObjectForKey:@"douglass.danmaku.rgb"];if([key isEqualToString:@"douglass.danmaku.font"])[NSUserDefaults.standardUserDefaults removeObjectForKey:@"douglass.danmaku.fontName"];if([key isEqualToString:@"douglass.eq.preset"]&&selected<4){const double values[4][3]={{0,0,0},{6,-1,1},{-2,4,1},{0,1,5}};NSArray *keys=@[@"douglass.eq.low",@"douglass.eq.mid",@"douglass.eq.high"];for(NSUInteger i=0;i<3;i++)[NSUserDefaults.standardUserDefaults setDouble:values[selected][i] forKey:keys[i]];[NSUserDefaults.standardUserDefaults setBool:YES forKey:@"douglass.eq.enabled"];[_table reloadData];}[self notifyKey:key];}
