- (void)documentPicker:(UIDocumentPickerViewController *)controller didPickDocumentsAtURLs:(NSArray<NSURL *> *)urls{NSURL *source=urls.firstObject;if(!source)return;BOOL scoped=[source startAccessingSecurityScopedResource];NSData *data=[NSData dataWithContentsOfURL:source];if(scoped)[source stopAccessingSecurityScopedResource];if(!data.length||data.length>30*1024*1024){DGToast(self,@"字体文件为空或超过 30MB");return;}NSURL *folder=[[NSFileManager.defaultManager URLsForDirectory:NSApplicationSupportDirectory inDomains:NSUserDomainMask].firstObject URLByAppendingPathComponent:@"Fonts" isDirectory:YES];[NSFileManager.defaultManager createDirectoryAtURL:folder withIntermediateDirectories:YES attributes:nil error:nil];NSURL *file=[folder URLByAppendingPathComponent:[NSUUID.UUID.UUIDString stringByAppendingPathExtension:source.pathExtension.lowercaseString]];[data writeToURL:file atomically:YES];CFArrayRef descriptors=CTFontManagerCreateFontDescriptorsFromURL((__bridge CFURLRef)file);NSArray *fonts=CFBridgingRelease(descriptors);if(!fonts.count){[NSFileManager.defaultManager removeItemAtURL:file error:nil];DGToast(self,@"文件不是可用字体");return;}CFErrorRef error=NULL;BOOL ok=CTFontManagerRegisterFontsForURL((__bridge CFURLRef)file,kCTFontManagerScopeProcess,&error);if(error)CFRelease(error);NSString *name=[(UIFontDescriptor *)fonts.firstObject objectForKey:UIFontDescriptorNameAttribute];if(!ok||!name.length){DGToast(self,@"字体无法加载");return;}[NSUserDefaults.standardUserDefaults setObject:name forKey:@"douglass.danmaku.fontName"];[self notifyKey:@"douglass.danmaku.fontName"];[_table reloadData];DGToast(self,@"字体已导入");}
- (void)rgb{NSArray *saved=[NSUserDefaults.standardUserDefaults arrayForKey:@"douglass.danmaku.rgb"]?:@[@255,@255,@255];UIAlertController *alert=[UIAlertController alertControllerWithTitle:@"自定义弹幕颜色" message:@"RGB 每项为 0～255" preferredStyle:UIAlertControllerStyleAlert];for(NSUInteger index=0;index<3;index++)[alert addTextFieldWithConfigurationHandler:^(UITextField *field){field.placeholder=@[@"R",@"G",@"B"][index];field.text=[saved[index]description];field.keyboardType=UIKeyboardTypeNumberPad;}];[alert addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[alert addAction:[UIAlertAction actionWithTitle:@"应用" style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){NSMutableArray *values=[NSMutableArray array];for(UITextField *field in alert.textFields){NSScanner *scanner=[NSScanner scannerWithString:field.text];NSInteger value;if(![scanner scanInteger:&value]||!scanner.isAtEnd||value<0||value>255){DGToast(self,@"请输入 0～255 的整数");return;}[values addObject:@(value)];}[NSUserDefaults.standardUserDefaults setObject:values forKey:@"douglass.danmaku.rgb"];[self notifyKey:@"douglass.danmaku.rgb"];}]];[self presentViewController:alert animated:YES completion:nil];}
- (void)tableView:(UITableView *)tableView didSelectRowAtIndexPath:(NSIndexPath *)path{
 [tableView deselectRowAtIndexPath:path animated:YES];NSDictionary *work=self.work;
 if(self.actions){NSInteger row=path.row;[self finish:^(UIViewController *host){NSString *image=Text(String(work[@"selectedImage"]));if(!image.length)image=Text(String(Array(work[@"images"]).firstObject));if(row==0){NSString *url=image.length?image:Text(String(work[@"play"]));if(!url.length)DGToast(host,@"平台未提供可保存的媒体地址");else DGSaveURL(host,url,!image.length);}else if(row==1){NSString *url=Text(String(work[@"cover"]));if(url.length)DGSaveURL(host,url,NO);else DGToast(host,@"该作品没有封面地址");}else if(row==2)DGSaveAudio(host,Text(String(work[@"music"])),Text(String(work[@"musicTitle"])));else if(row==3)DGConfirmCopy(host,Text(String(work[@"caption"])));else{NSString *identifier=Text(String(work[@"id"]));if(!identifier.length){DGToast(host,@"没有可分享的作品标识");return;}UIPasteboard.generalPasteboard.string=[NSString stringWithFormat:@"https://www.douyin.com/%@/%@",image.length?@"note":@"video",identifier];DGHaptic();DGToast(host,@"分享链接已复制");}}];return;}
 NSDictionary *row=[self rows][path.section][path.row];NSString *action=row[@"action"];if([action isEqualToString:@"font"]){UIFontPickerViewControllerConfiguration *configuration=[UIFontPickerViewControllerConfiguration new];configuration.includeFaces=YES;UIFontPickerViewController *picker=[[UIFontPickerViewController alloc]initWithConfiguration:configuration];picker.delegate=self;[self presentViewController:picker animated:YES completion:nil];}
